import {BUILD,message,clearRoomAssignment,path,W,hub} from './engine.js';
export const RESOURCE_NAMES={food:'Пища',water:'Питьевая вода',energy:'Энергия',material:'Материалы',metal:'Металл',fuel:'Топливо',tools:'Инструменты',stone:'Порода',groundwater:'Подземная вода',ore:'Руда',gold:'Золото',uranium:'Уран',nuclearFuel:'Ядерное топливо',science:'Научные данные'};
export const capacity=s=>250+s.cells.filter(c=>c.building==='storage').length*600;
const autoTypes=['water','farm','quarry','drill','mine','smelter','goldMine','uraniumMine'];
const passive=['home','storage','corridor','stairs'];
export function recipe(s,c){switch(c.building){case 'goldMine':return {input:{goldDeposit:.18},output:{gold:.18}};case 'uraniumMine':return {input:{uraniumDeposit:.35},output:{uranium:.35}};case 'mine':return {input:{oreDeposit:.4},output:{ore:.4}};case 'smelter':return {input:{ore:.3,fuel:.06},output:{metal:.15}};case 'generator':return {input:{fuel:.12},output:{energy:5*(1+s.tech*.05)*(s.unlocks.includes('energy')?1.35:1)}};case 'water':return {input:{groundwater:.65},output:{water:.65}};case 'farm':return {input:{water:.2/3},output:{food:.7*(s.unlocks.includes('farming')?1.4:1)}};case 'drill':return {input:{deposit:.32*(s.unlocks.includes('drilling')?1.5:1)},output:{fuel:.32*(s.unlocks.includes('drilling')?1.5:1)}};case 'quarry':return {input:{stone:.4},output:{material:.25}};case 'workshop':return {input:{metal:.025},output:{tools:.05}};case 'lab':return {input:{metal:.005},output:{science:.06}};case 'med':return {input:{water:.03/3},output:{}};default:return {input:{},output:{}};}}
// Buffers are reserved portions of the shared stock, never extra resources.
const supplyBufferCache=new WeakMap(),supplyPathCache=new WeakMap();
export const supplyInputs={smelter:'ore',generator:'fuel',farm:'water',quarry:'stone',workshop:'metal',lab:'metal',med:'water'};
export function freeStock(s,k){if(!['fuel','water','stone','metal','ore'].includes(k))return s.resources[k];let cells=supplyBufferCache.get(s)||s.cells.filter(c=>c.supply);return Math.max(0,s.resources[k]-cells.reduce((n,c)=>n+(c.supply?.[k]||0),0));}
export function supplyCapacity(s,c,k=supplyInputs[c.building]){return k?recipe(s,c).input[k]*(s.unlocks.includes('freight')?60:30):0;}
export function inputStock(s,c,k){return k==='oreDeposit'?c.oreReserve:k==='goldDeposit'?c.goldReserve:k==='uraniumDeposit'?c.uraniumReserve:k==='deposit'?c.fuelReserve:deliveryKeys(c).includes(k)?Math.min(s.resources[k],c.supply?.[k]||0):s.resources[k];}
export function supplyRoute(s,c,knownStamp=null){let stamp=knownStamp||s.cells.map(n=>n.type==='open'?(n.building==='stairs'?'L':n.building==='storage'?'S':'.'):'#').join('');let cached=supplyPathCache.get(s);if(!cached||cached.stamp!==stamp){cached={stamp,routes:new Map()};supplyPathCache.set(s,cached);}let key=c.x+','+c.y;if(cached.routes.has(key))return cached.routes.get(key);let best=null;for(let source of s.cells.filter(n=>n.building==='storage')){if(path(s,hub(s),source)===null)continue;let route=path(s,source,c);if(route!==null&&(!best||route.length<best.route.length))best={source,route};}cached.routes.set(key,best);return best;}
export function deliveryKeys(c){return c.building==='smelter'?['ore','fuel']:supplyInputs[c.building]?[supplyInputs[c.building]]:[];}
export function automaticSupply(s,dt){let stamp=s.cells.map(n=>n.type==='open'?(n.building==='stairs'?'L':n.building==='storage'?'S':'.'):'#').join('');s.supplyTime=s.time;for(let c of s.cells){let keys=deliveryKeys(c);if(!keys.length){delete c.supply;continue;}c.supply=c.supply||{};for(let k of Object.keys(c.supply))if(!keys.includes(k))delete c.supply[k];for(let k of keys)c.supply[k]=Math.max(0,Math.min(c.supply[k]||0,supplyCapacity(s,c,k)));}supplyBufferCache.set(s,s.cells.filter(c=>c.supply));for(let k of ['fuel','water','stone','metal','ore']){let left=s.resources[k];for(let c of s.cells)if(c.supply?.[k]){c.supply[k]=Math.min(c.supply[k],left);left-=c.supply[k];}}
for(let c of s.cells){let keys=deliveryKeys(c);if(!keys.length)continue;c.delivery=0;c.deliveryRates={};if(c.enabled===false||s.jobs.some(j=>j.type==='dismantle'&&j.x===c.x&&j.y===c.y)||c.building==='med'&&!s.people.some(p=>p.health>0&&p.health<100)||Object.keys(recipe(s,c).output).some(key=>key!=='energy'&&(key==='science'?s.researchPoints:s.resources[key])>=outputLimit(s,c,key))){for(let k of keys)c.supply[k]=0;continue;}let route=supplyRoute(s,c,stamp);if(!route)continue;for(let k of keys){let amount=Math.max(0,Math.min(freeStock(s,k),supplyCapacity(s,c,k)-c.supply[k],dt*(s.unlocks.includes('freight')?4:2)/(1+route.route.length*.2)));c.supply[k]+=amount;c.deliveryRates[k]=amount/dt;c.delivery+=amount/dt;}}}
export function stockFull(s){let cap=capacity(s);return ['food','water','energy','material','metal','fuel','tools','stone','ore','gold','uranium','nuclearFuel'].filter(k=>s.resources[k]>=cap-1e-7);}

// Shared eligibility: workers and room telemetry use the same physical conditions.
export function outputLimit(s,c,key,cap=capacity(s)){let base=key==='science'?1000:cap;return Math.min(base,c.productionTarget||base);}
export function operationBlock(s,c,cap=capacity(s)){if(c.enabled===false)return 'остановлено игроком';if(s.jobs.some(j=>j.type==='dismantle'&&j.x===c.x&&j.y===c.y))return 'назначена разборка';if(passive.includes(c.building)||!c.building)return null;let r=recipe(s,c);for(let [k,v] of Object.entries(r.input))if(v>0&&inputStock(s,c,k)<=0)return k==='oreDeposit'?'руда исчерпана':k==='deposit'?'залежь исчерпана':k==='groundwater'?'подземная вода исчерпана':s.resources[k]>0&&deliveryKeys(c).includes(k)?'ожидает автоматическую доставку '+RESOURCE_NAMES[k].toLowerCase():'нет запаса: '+RESOURCE_NAMES[k].toLowerCase();if(c.building!=='generator'&&s.resources.energy<=0)return 'нет энергии';for(let [k,v] of Object.entries(r.output))if(v>0&&(k==='science'?s.researchPoints>=outputLimit(s,c,k,cap):s.resources[k]>=outputLimit(s,c,k,cap))&&k!=='energy')return c.productionTarget?'достигнут заданный запас':'запас '+RESOURCE_NAMES[k].toLowerCase()+' полон';if(c.building==='med'&&!s.people.some(p=>p.health>0&&p.health<100))return 'все жители здоровы';if(c.building==='radio'&&s.arrivals>=30)return 'очередь выживших заполнена';return null;}
export function workers(s){let groups={free:[],operators:[],builders:[],resting:[],moving:[],dead:[]};for(let p of s.people){if(p.health<=0)groups.dead.push(p);else if(p.task==='Отдых')groups.resting.push(p);else if(p.campaignProject)groups.builders.push(p);else if(p.expedition)groups.moving.push(p);else if(p.job)groups.builders.push(p);else if(p.target&&s.cells[p.target.y*W+p.target.x]?.building&&!['home','storage','corridor','stairs'].includes(s.cells[p.target.y*W+p.target.x].building))groups.operators.push(p);else if(p.path.length)groups.moving.push(p);else groups.free.push(p);}return groups;}
export function releaseBuilder(s,manual=true){let order=['lab','radio','vent','quarry','workshop','med','farm','water','drill','generator'];let candidates=s.people.filter(p=>p.health>0&&!p.campaignProject&&!p.expedition&&p.fatigue<=50&&p.task!=='Отдых'&&!p.job&&(manual||p.priority!=='operate'));candidates.sort((a,b)=>{let score=p=>!p.target||['home','storage','corridor','stairs'].includes(s.cells[p.target.y*W+p.target.x]?.building)?-10:order.indexOf(s.cells[p.target.y*W+p.target.x]?.building);return score(a)-score(b)||b.skill-a.skill;});let p=candidates.find(p=>p.priority!=='build');if(!p)return 'Нет доступного жителя: все строят, отдыхают или закреплены за оборудованием';for(let c of s.cells)if(c.preferredOperator===p.id)clearRoomAssignment(s,c);let old=p.target?s.cells[p.target.y*W+p.target.x]?.building:null;p.priority='build';p.reservedBuilder=!manual;p.target=null;p.path=[];p.task='Ожидание';s.metrics=null;message(s,p.name+' назначен строителем'+(old&&BUILD[old]?' · '+BUILD[old].name+' освобождён':''));return null;}
function staff(s,c){return s.people.filter(p=>p.health>0&&!p.campaignProject&&!p.expedition&&!p.path.length&&!p.job&&p.target?.x===c.x&&p.target?.y===c.y&&!['Отдых','Свободен'].includes(p.task));}
function baseReport(s,c){let automatic=s.unlocks.includes('automation')&&autoTypes.includes(c.building),people=staff(s,c),r=recipe(s,c);return {key:c.x+','+c.y,building:c.building,staff:people.map(p=>p.id),automatic,input:r.input,output:r.output,actualInput:{},actualOutput:{},utilization:0,power:BUILD[c.building]?.power+(automatic?.2:0)||0,status:'Ожидание',reason:'нет оператора'};}
export function roomReport(s,c){let saved=s.metrics?.rooms?.[c.x+','+c.y];if(saved&&s.metrics.time===s.time)return saved;let m=baseReport(s,c);if(!c.building){m.status='Пусто';m.reason='доступно для строительства';return m;}let blocked=operationBlock(s,c);if(blocked){m.status=blocked==='назначена разборка'?'Разборка':'Остановлено';m.reason=blocked;return m;}if(passive.includes(c.building)){m.status='Доступно';m.reason='';return m;}let cap=capacity(s);if(!m.automatic&&!m.staff.length){let approaching=s.people.find(p=>p.health>0&&p.target?.x===c.x&&p.target?.y===c.y&&p.path.length);m.reason=approaching?approaching.name+' идёт к оборудованию':'нет оператора';return m;}if(c.building!=='generator'&&s.resources.energy<=0){m.reason='нет энергии';return m;}for(let [k,v] of Object.entries(m.input)){if(v>0&&inputStock(s,c,k)<=0){m.reason=k==='oreDeposit'?'руда исчерпана':k==='deposit'?'залежь исчерпана':k==='groundwater'?'подземная вода исчерпана':'нет запаса: '+RESOURCE_NAMES[k]?.toLowerCase();return m;}}for(let [k,v] of Object.entries(m.output))if(v>0&&k!=='science'&&s.resources[k]>=cap){m.reason=c.productionTarget?'достигнут заданный запас':'запас '+RESOURCE_NAMES[k].toLowerCase()+' полон';return m;}m.status='Готово';m.reason='показания появятся после следующего шага';return m;}
export function runEconomy(s,dt,operators,live,previous){if(s.supplyTime!==s.time)automaticSupply(s,dt);let r=s.resources,cap=capacity(s),rooms={},production={},consumption={};const add=(obj,k,v)=>obj[k]=(obj[k]||0)+v;let metered=(m,kind,k,amount)=>{if(amount<=0)return;add(kind==='input'?m.actualInput:m.actualOutput,k,amount/dt);if(!['deposit','oreDeposit','goldDeposit','uraniumDeposit'].includes(k))add(kind==='input'?consumption:production,k,amount/dt);};for(let k of Object.keys(r)){let delta=r[k]-previous[k];if(delta>0)add(production,k,delta/dt);else if(delta<0)add(consumption,k,-delta/dt);}
for(let c of s.cells)if(c.building)rooms[c.x+','+c.y]=baseReport(s,c);
let valid=[...operators].filter(c=>c.building&&c.enabled!==false&&!passive.includes(c.building)&&!s.jobs.some(j=>j.type==='dismantle'&&j.x===c.x&&j.y===c.y));let demand=live.length*.08+valid.filter(c=>c.building!=='generator').reduce((sum,c)=>{let m=rooms[c.x+','+c.y],fraction=1;for(let [k,v] of Object.entries(m.input))fraction=Math.min(fraction,Math.max(0,inputStock(s,c,k)/(v*dt)));for(let [k,v] of Object.entries(m.output))fraction=Math.min(fraction,Math.max(0,(k==='science'?outputLimit(s,c,k,cap)-s.researchPoints:outputLimit(s,c,k,cap)-r[k])/(v*dt)));if(c.building==='med'&&!live.some(p=>p.health<100)||c.building==='radio'&&s.arrivals>=30)fraction=0;return sum+m.power*fraction;},0);let need=Math.max(0,cap-r.energy+dt*demand);
for(let c of valid.filter(c=>c.building==='generator')){let m=rooms[c.x+','+c.y],eff=m.output.energy,amount=Math.min(need,Math.max(0,outputLimit(s,c,'energy',cap)-r.energy+dt*demand),dt*eff,inputStock(s,c,'fuel')*eff/.12);c.supply=c.supply||{};c.supply.fuel=Math.max(0,(c.supply.fuel||0)-amount*.12/eff);r.fuel-=amount*.12/eff;r.energy+=amount;need-=amount;metered(m,'input','fuel',amount*.12/eff);metered(m,'output','energy',amount);m.utilization=amount/(dt*eff);m.status=amount>0?'Работает':'Остановлено';m.reason=amount>0?(m.utilization<.999?'снижение мощности по потребности':''):r.fuel<=0?'нет топлива':inputStock(s,c,'fuel')<=0?'ожидает автоматическую доставку топлива':'энергии достаточно';}
let lifePower=Math.min(r.energy,live.length*.08*dt);r.energy-=lifePower;add(consumption,'energy',lifePower/dt);
for(let c of valid.filter(c=>c.building!=='generator')){let m=rooms[c.x+','+c.y],fraction=1,reason='';for(let [k,v] of Object.entries(m.input)){let stock=inputStock(s,c,k);let f=stock/(v*dt);if(f<fraction){fraction=Math.max(0,f);reason=k==='oreDeposit'?'руда исчерпана':k==='deposit'?'залежь исчерпана':k==='groundwater'?'подземная вода исчерпана':'не хватает '+RESOURCE_NAMES[k].toLowerCase();}}
for(let [k,v] of Object.entries(m.output)){let headroom=k==='science'?outputLimit(s,c,k,cap)-s.researchPoints:outputLimit(s,c,k,cap)-r[k],f=headroom/(v*dt);if(f<fraction){fraction=Math.max(0,f);reason=c.productionTarget?'достигнут заданный запас':'запас '+RESOURCE_NAMES[k].toLowerCase()+' полон';}}
if(c.building==='radio'&&s.arrivals>=30){fraction=0;reason='очередь выживших заполнена';}if(c.building==='med'&&!live.some(p=>p.health<100)){fraction=0;reason='все жители здоровы';}if(m.power>0){let f=r.energy/(m.power*dt);if(f<fraction){fraction=Math.max(0,f);reason='не хватает энергии';}}
fraction=Math.min(1,Math.max(0,fraction));let energy=m.power*dt*fraction;r.energy-=energy;metered(m,'input','energy',energy);
for(let [k,v] of Object.entries(m.input)){let amount=v*dt*fraction;if(k==='oreDeposit')c.oreReserve=Math.max(0,c.oreReserve-amount);else if(k==='goldDeposit')c.goldReserve=Math.max(0,c.goldReserve-amount);else if(k==='uraniumDeposit')c.uraniumReserve=Math.max(0,c.uraniumReserve-amount);else if(k==='deposit')c.fuelReserve=Math.max(0,c.fuelReserve-amount);else {r[k]=Math.max(0,r[k]-amount);if(deliveryKeys(c).includes(k)){c.supply=c.supply||{};c.supply[k]=Math.max(0,(c.supply[k]||0)-amount);};}metered(m,'input',k,amount);}for(let [k,v] of Object.entries(m.output)){let amount=v*dt*fraction;if(k==='science')s.researchPoints+=amount;else r[k]+=amount;metered(m,'output',k,amount);}
if(c.building==='lab'&&fraction>0)s.tech=Math.min(5,s.tech+dt*.001*fraction);if(c.building==='med')for(let p of live)p.health=Math.min(100,p.health+dt*.025*fraction);if(c.building==='radio'){s.signalTime+=dt*fraction;if(s.signalTime>=180){s.signalTime-=180;s.arrivals=Math.min(30,s.arrivals+3);message(s,'Радиосигнал услышан: ещё 3 выживших у входа.');}m.progress=s.signalTime/180;}
m.utilization=fraction;m.status=fraction>0?'Работает':'Остановлено';m.reason=reason;if(c.building==='drill'&&c.fuelReserve===0&&!c.exhaustedNotified){c.exhaustedNotified=true;message(s,'Топливная залежь исчерпана. Ищи следующую.');}}
for(let c of s.cells)if(c.building&&!valid.includes(c)){let m=rooms[c.x+','+c.y],blocked=operationBlock(s,c,cap);if(blocked){m.status=blocked==='назначена разборка'?'Разборка':'Остановлено';m.reason=blocked;}else if(passive.includes(c.building)){m.status='Доступно';m.reason='';}else{let incoming=s.people.find(p=>p.health>0&&p.path.length&&p.target?.x===c.x&&p.target?.y===c.y);m.reason=incoming?incoming.name+' идёт к оборудованию':'нет оператора';}}
for(let k of Object.keys(r)){let spilled=k==='groundwater'?0:Math.max(0,r[k]-cap);if(spilled>0)add(consumption,k,spilled/dt);r[k]=Math.max(0,k==='groundwater'?r[k]:Math.min(cap,r[k]));}let net={};for(let k of Object.keys(r))net[k]=(r[k]-previous[k])/dt;s.metrics={time:s.time,rooms,production,consumption,net,groundwaterUse:consumption.groundwater||0};}
export function reserveTime(stock,rate){return stock<=0?0:rate>1e-8?stock/rate:null;}
export function barData(s,c){let m=roomReport(s,c),cap=capacity(s);if(c.building==='goldMine')return {label:'Золотая жила',value:c.goldReserve||0,max:c.goldMax||1,color:'#e5c35a',m};if(c.building==='uraniumMine')return {label:'Урановая залежь',value:c.uraniumReserve||0,max:c.uraniumMax||1,color:'#a7d77c',m};if(c.building==='mine')return {label:c.largeDeposit?'Большой рудник':'Рудная залежь',value:c.oreReserve||0,max:c.oreMax||1,color:'#d6b6fa',m};if(c.building==='smelter')return {label:'Руда',value:s.resources.ore,max:cap,color:'#d6b6fa',m};if(c.building==='drill')return {label:c.largeDeposit?'Большое топливо':'Залежь',value:c.fuelReserve||0,max:c.fuelMax||c.fuelReserve||1,color:'#f5ca78',m};if(c.building==='water')return {label:'Водоносный слой',value:s.resources.groundwater,max:s.groundwaterMax||4000,color:'#78ddef',m};if(c.building==='home')return {label:'Жильё',value:s.people.filter(p=>p.health>0&&Math.round(p.x)===c.x&&Math.round(p.y)===c.y).length,max:8,color:'#f3c184',m};if(c.building==='storage')return {label:'Запасы',value:['food','water','energy','material','metal','fuel','tools','ore'].reduce((a,k)=>a+s.resources[k],0),max:cap*8,color:'#ecd186',m};let key=({generator:'fuel',farm:'food',quarry:'stone',workshop:'metal',lab:'science',med:'water',radio:'arrival',vent:'energy'})[c.building];return {label:key==='science'?'Данные':key==='arrival'?'Сигнал':RESOURCE_NAMES[key]||'Доступ',value:key==='science'?s.researchPoints:key==='arrival'?s.signalTime:s.resources[key]||0,max:key==='science'?1000:key==='arrival'?180:cap,color:({generator:'#ffd77c',farm:'#ade886',med:'#ffa3b0'})[c.building]||'#9dcfea',m};}

export function bunkerWarnings(s){let warnings=[];for(let k of ['food','water','energy','fuel','groundwater']){let stock=s.resources[k],draw=k==='groundwater'?s.metrics?.groundwaterUse||0:Math.max(0,-(s.metrics?.net[k]||0));let seconds=reserveTime(stock,draw);if(stock<15||seconds!==null&&seconds<=600){let text=RESOURCE_NAMES[k]+': '+(stock<=0?'запас закончился':seconds!==null?'запас примерно на '+Math.ceil(seconds/60)+' мин симуляции':'осталось '+Math.floor(stock));warnings.push({key:k,seconds,text});}}return warnings.sort((a,b)=>(a.seconds===null?Infinity:a.seconds)-(b.seconds===null?Infinity:b.seconds));}
